package cmd

import (
	"fmt"
	"os"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/mightymoud/arlocode/internal/bridge"
	"github.com/mightymoud/arlocode/internal/butler/memory"
	"github.com/mightymoud/arlocode/internal/coding_agent"
	"github.com/mightymoud/arlocode/internal/tui/app"
	"github.com/spf13/cobra"
)

// Version information - set via ldflags at build time
var (
	version = "dev"
	commit  = "none"
	date    = "unknown"
)

var systemPrompt = `You are ArloCode, an AI coding agent designed to assist developers with complex coding tasks.
You have access to various tools to help you accomplish your goals.
You should think carefully about which tools to use and when to use them.
You should also provide reasoning for your actions to help the user understand your thought process.

When you need to use a tool, you must specify the tool name and provide the necessary arguments in JSON format.
After executing a tool, you should analyze the results and decide on the next steps.

Always aim to provide clear and concise explanations for your actions and decisions.
Your ultimate goal is to assist the user in completing their coding tasks effectively and efficiently.
`

// rootCmd represents the base command when called without any subcommands
var rootCmd = &cobra.Command{
	Use:   "arlocode",
	Short: "ArloCode a Coding Agent focused on long running tasks and local models",
	Long:  `AlroCode is an AI coding agent designed to assist developers with complex coding tasks.`,
	Run: func(cmd *cobra.Command, args []string) {
		codingAgent := coding_agent.Agent.WithMaxIterations(30).WithMemory([]memory.MemoryEntry{
			{
				StepID:  1,
				Source:  "system",
				Message: systemPrompt,
			},
		})
		agentBridge := bridge.NewDirectBridge(codingAgent)

		// Create the app model using the new constructor
		m := app.NewAppModel(agentBridge)

		p := tea.NewProgram(m, tea.WithAltScreen(), tea.WithMouseCellMotion())

		go func() {
			for event := range agentBridge.Events() {
				switch e := event.(type) {
				case bridge.TextChunkEvent:
					p.Send(app.AgentTextChunkMsg(e.Text))
				case bridge.TextCompleteEvent:
					p.Send(app.AgentTextCompleteMsg(""))
				case bridge.ThinkingChunkEvent:
					p.Send(app.AgentThinkingChunkMsg(e.Text))
				case bridge.ThinkingCompleteEvent:
					p.Send(app.AgentThinkingCompleteMsg(""))
				case bridge.ToolCallEvent:
					p.Send(app.ToolCallMsg(e.ToolCall))
				case bridge.ErrorEvent:
					// Handle error event if needed
				case bridge.TurnCompleteEvent:
					// Handle turn complete event if needed
				}
			}
		}()
		if _, err := p.Run(); err != nil {
			fmt.Printf("Error: %v", err)
			os.Exit(1)
		}
	},
}

// Execute adds all child commands to the root command and sets flags appropriately.
// This is called by main.main(). It only needs to happen once to the rootCmd.
func Execute() {
	err := rootCmd.Execute()
	if err != nil {
		os.Exit(1)
	}
}

func init() {
	// Here you will define your flags and configuration settings.
	// Cobra supports persistent flags, which, if defined here,
	// will be global for your application.

	// Set version template for --version flag
	rootCmd.Version = version
	rootCmd.SetVersionTemplate(fmt.Sprintf("arlocode %s (commit: %s, built: %s)\n", version, commit, date))
}

package agent

import (
	"context"
	"testing"

	"github.com/mightymoud/arlocode/internal/butler"
	"github.com/mightymoud/arlocode/internal/butler/memory"
	"github.com/mightymoud/arlocode/internal/butler/providers"
	"github.com/mightymoud/arlocode/internal/butler/tools"
)

// MockLLM is a mock implementation of the LLM interface
type MockLLM struct {
	StreamFunc   func(ctx context.Context, mem []memory.MemoryEntry, t []tools.Tool, hooks butler.EventHooks) (providers.ProviderResponse, error)
	GenerateFunc func(ctx context.Context, mem []memory.MemoryEntry, t []tools.Tool, hooks butler.EventHooks) error
}

func (m *MockLLM) Stream(ctx context.Context, mem []memory.MemoryEntry, t []tools.Tool, hooks butler.EventHooks) (providers.ProviderResponse, error) {
	if m.StreamFunc != nil {
		return m.StreamFunc(ctx, mem, t, hooks)
	}
	return providers.ProviderResponse{}, nil
}

func (m *MockLLM) Generate(ctx context.Context, mem []memory.MemoryEntry, t []tools.Tool, hooks butler.EventHooks) error {
	if m.GenerateFunc != nil {
		return m.GenerateFunc(ctx, mem, t, hooks)
	}
	return nil
}

func TestNewAgent(t *testing.T) {
	mockLLM := &MockLLM{}
	agent := NewAgent(mockLLM)

	if agent == nil {
		t.Fatal("NewAgent returned nil")
	}
	if agent.llm != mockLLM {
		t.Errorf("Expected llm to be %v, got %v", mockLLM, agent.llm)
	}
	if len(agent.memory) != 0 {
		t.Errorf("Expected empty memory, got %v", agent.memory)
	}
	if len(agent.tools) == 0 {
		t.Error("Expected default tools, got empty")
	}
}

func TestAgent_WithMemory(t *testing.T) {
	mockLLM := &MockLLM{}
	agent := NewAgent(mockLLM)
	mem := []memory.MemoryEntry{{StepID: 1, Message: "test", Source: "user"}}

	agent.WithMemory(mem)
	if len(agent.memory) != 1 || agent.memory[0].Message != "test" {
		t.Errorf("WithMemory failed")
	}
}

func TestAgent_WitTools(t *testing.T) {
	mockLLM := &MockLLM{}
	agent := NewAgent(mockLLM)
	newTools := []tools.Tool{}

	agent.WitTools(newTools)
	if len(agent.tools) != 0 {
		t.Errorf("WitTools failed")
	}
}

func TestAgent_WithNoTools(t *testing.T) {
	mockLLM := &MockLLM{}
	agent := NewAgent(mockLLM)

	agent.WithNoTools()
	if len(agent.tools) != 0 {
		t.Errorf("WithNoTools failed")
	}
}

func TestAgent_AddMemoryEntry(t *testing.T) {
	mockLLM := &MockLLM{}
	agent := NewAgent(mockLLM)
	entry := memory.MemoryEntry{StepID: 1, Message: "test", Source: "user"}

	agent.AddMemoryEntry(entry)
	if len(agent.memory) != 1 {
		t.Errorf("AddMemoryEntry failed")
	}
}

func TestAgent_GetMemory(t *testing.T) {
	mockLLM := &MockLLM{}
	agent := NewAgent(mockLLM)
	entry := memory.MemoryEntry{StepID: 1, Message: "test", Source: "user"}
	agent.AddMemoryEntry(entry)

	mem := agent.GetMemory()
	if len(mem) != 1 {
		t.Errorf("GetMemory failed")
	}
}

type MockToolArgs struct {
	Input string `json:"input"`
}

func MockToolHandler(args MockToolArgs) (string, error) {
	return "processed: " + args.Input, nil
}

func TestAgent_HandleToolCall(t *testing.T) {
	mockLLM := &MockLLM{}
	agent := NewAgent(mockLLM)

	mockTool := tools.NewButlerTool("mock_tool", "mock description", MockToolHandler)
	agent.WitTools([]tools.Tool{mockTool})

	call := tools.ToolCall{
		ID:           "call_1",
		FunctionName: "mock_tool",
		Arguments:    map[string]any{"input": "test"},
	}

	result, err := agent.HandleToolCall(context.Background(), call)
	if err != nil {
		t.Fatalf("HandleToolCall failed: %v", err)
	}
	if result != "processed: test" {
		t.Errorf("Expected 'processed: test', got '%s'", result)
	}
}

func TestAgent_Run(t *testing.T) {
	mockLLM := &MockLLM{
		StreamFunc: func(ctx context.Context, mem []memory.MemoryEntry, t []tools.Tool, hooks butler.EventHooks) (providers.ProviderResponse, error) {
			return providers.ProviderResponse{
				Text: "world",
			}, nil
		},
	}
	agent := NewAgent(mockLLM)
	agent.WithNoTools()

	ctx := context.Background()
	prompt := "hello"

	err := agent.Run(ctx, prompt)
	if err != nil {
		t.Fatalf("Run failed: %v", err)
	}

	mem := agent.GetMemory()
	if len(mem) != 2 {
		t.Fatalf("Expected 2 memory entries, got %d", len(mem))
	}
	if mem[0].Message != "hello" {
		t.Errorf("Expected first message 'hello', got '%s'", mem[0].Message)
	}
	if mem[1].Message != "world" {
		t.Errorf("Expected second message 'world', got '%s'", mem[1].Message)
	}
}

func TestAgent_Run_WithToolCall(t *testing.T) {
	mockTool := tools.NewButlerTool("mock_tool", "mock description", MockToolHandler)

	callCount := 0
	mockLLM := &MockLLM{
		StreamFunc: func(ctx context.Context, mem []memory.MemoryEntry, t []tools.Tool, hooks butler.EventHooks) (providers.ProviderResponse, error) {
			callCount++
			if callCount == 1 {
				return providers.ProviderResponse{
					Text: "I will use the tool",
					ToolCalls: []tools.ToolCall{
						{
							ID:           "call_1",
							FunctionName: "mock_tool",
							Arguments:    map[string]any{"input": "test"},
						},
					},
				}, nil
			}
			return providers.ProviderResponse{
				Text: "Final answer",
			}, nil
		},
	}

	agent := NewAgent(mockLLM)
	agent.WitTools([]tools.Tool{mockTool})

	ctx := context.Background()
	prompt := "do something"

	err := agent.Run(ctx, prompt)
	if err != nil {
		t.Fatalf("Run failed: %v", err)
	}

	mem := agent.GetMemory()
	// 1. User prompt
	// 2. Agent response with tool call + observation
	// 3. Agent response (final)
	if len(mem) != 3 {
		t.Fatalf("Expected 3 memory entries, got %d", len(mem))
	}
	if len(mem[1].Observation.Results) != 1 {
		t.Fatalf("Expected 1 observation result, got %d", len(mem[1].Observation.Results))
	}
	if mem[1].Observation.Results[0].Content != "processed: test" {
		t.Errorf("Expected tool output 'processed: test', got '%s'", mem[1].Observation.Results[0].Content)
	}
}

