package agent

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"reflect"
	"strings"

	"github.com/fatih/color"
	"github.com/mightymoud/arlocode/internal/butler"
	"github.com/mightymoud/arlocode/internal/butler/llm"
	"github.com/mightymoud/arlocode/internal/butler/memory"
	"github.com/mightymoud/arlocode/internal/butler/tools"
)

type Agent struct {
	llm                llm.LLM
	memory             []memory.MemoryEntry
	tools              []tools.Tool
	maxIterations      int
	ModelName          string
	OnTextChunk        butler.OnTextChunkFunc
	OnTextComplete     butler.OnTextCompleteFunc
	OnThinkingChunk    butler.OnThinkingChunkFunc
	OnThinkingComplete butler.OnThinkingCompleteFunc
	OnToolCall         butler.OnToolCallFunc
	OnTurnComplete     butler.OnTurnCompleteFunc
}

func NewAgent(l llm.LLM) *Agent {
	return &Agent{
		llm:           l,
		memory:        []memory.MemoryEntry{},
		tools:         tools.StdToolset,
		maxIterations: 10, // Default max iterations as recommended by OpenRouter docs
		ModelName:     "unknown",
	}
}

// Mods
func (a *Agent) WithMemory(memory []memory.MemoryEntry) *Agent {
	a.memory = memory
	return a
}

func (a *Agent) WithModelName(modelName string) *Agent {
	a.ModelName = modelName
	return a
}

func (a *Agent) WitTools(tools []tools.Tool) *Agent {
	a.tools = tools
	return a
}

func (a *Agent) WithNoTools() *Agent {
	a.tools = []tools.Tool{}
	return a
}

func (a *Agent) WithMaxIterations(max int) *Agent {
	a.maxIterations = max
	return a
}

func (l *Agent) WithOnThinkingChunk(f butler.OnThinkingChunkFunc) *Agent {
	l.OnThinkingChunk = f
	return l
}

func (l *Agent) WithOnThinkingComplete(f butler.OnThinkingCompleteFunc) *Agent {
	l.OnThinkingComplete = f
	return l
}

func (l *Agent) WithOnTextChunk(f butler.OnTextChunkFunc) *Agent {
	l.OnTextChunk = f
	return l
}

func (l *Agent) WithOnTextComplete(f butler.OnTextCompleteFunc) *Agent {
	l.OnTextComplete = f
	return l
}

func (l *Agent) WithOnToolCall(f butler.OnToolCallFunc) *Agent {
	l.OnToolCall = f
	return l
}

func (l *Agent) WithOnTurnComplete(f butler.OnTurnCompleteFunc) *Agent {
	l.OnTurnComplete = f
	return l
}

// Mock for Memory stuff later this is where Agent will use it
func (a *Agent) AddMemoryEntry(entry memory.MemoryEntry) {
	a.memory = append(a.memory, entry)
}

// Memory stuff later
func (a *Agent) GetMemory() []memory.MemoryEntry {
	return a.memory
}

func (a *Agent) HandleToolCall(ctx context.Context, call tools.ToolCall) (string, error) {
	var tool tools.Tool
	for _, t := range a.tools {
		if t.Name == call.FunctionName {
			tool = t
			break
		}
	}

	argsPtr := reflect.New(tool.ArgType).Interface()

	// Convert the map[string]any into the concrete struct.
	// This works for ANY provider because we go through JSON bytes first.
	bytes, _ := json.Marshal(call.Arguments)
	if err := json.Unmarshal(bytes, argsPtr); err != nil {
		return "", fmt.Errorf("failed to unmarshal tool args: %w", err)
	}

	results := tool.Handler.Call([]reflect.Value{
		reflect.ValueOf(argsPtr).Elem(),
	})

	if len(results) > 1 && !results[1].IsNil() {
		return "", results[1].Interface().(error)
	}
	resultStr := results[0].String()

	if a.OnToolCall != nil {
		a.OnToolCall(tools.ToolCall{
			ID:           "toolID", // TODO: generate unique ID for tool call
			FunctionName: tool.Name,
			Arguments:    call.Arguments,
		})
	}
	// Maybe useful to debug later
	// if len(resultStr) > 100 {
	// 	color.Blue("Tool %s returned: %s", call.FunctionName, resultStr[:100])
	// } else {
	// 	color.Blue("Tool %s returned: %s", call.FunctionName, resultStr)
	// }

	return resultStr, nil
}

func (a *Agent) Run(ctx context.Context, prompt string) error {
	initMessage := memory.MemoryEntry{
		StepID:  a.nextStepID(),
		Source:  "user",
		Message: prompt,
	}
	a.AddMemoryEntry(initMessage)

	iterationCount := 0
	for iterationCount < a.maxIterations {
		iterationCount++

		var reasoning strings.Builder
		hooks := butler.EventHooks{
			OnTextChunk:    a.OnTextChunk,
			OnTextComplete: a.OnTextComplete,
			OnToolCall:     a.OnToolCall,
			OnTurnComplete: a.OnTurnComplete,
			OnThinkingChunk: func(chunk string) {
				reasoning.WriteString(chunk)
				if a.OnThinkingChunk != nil {
					a.OnThinkingChunk(chunk)
				}
			},
			OnThinkingComplete: func() {
				if a.OnThinkingComplete != nil {
					a.OnThinkingComplete()
				}
			},
		}

		result, err := a.llm.Stream(ctx, a.memory, a.tools, hooks)
		if err != nil {
			log.Fatal("Error calling LLM Stream: ", err)
			return err
		}

		entry := memory.MemoryEntry{
			StepID:  a.nextStepID(),
			Source:  "agent",
			Message: result.Text,
		}
		if reasoning.Len() > 0 {
			entry.ReasoningContent = reasoning.String()
		}
		if result.Metrics != nil {
			entry.Metrics = *result.Metrics
		}
		if len(result.ToolCalls) > 0 {
			entry.ToolCalls = mapToolCalls(result.ToolCalls)
		}

		if len(result.ToolCalls) > 0 {
			var results []memory.ObservationResult
			for _, call := range result.ToolCalls {
				// Ask user for confirmation before executing tool
				// var confirm bool
				// if err := huh.NewConfirm().
				// 	Title("Execute tool?").
				// 	Description(fmt.Sprintf("Do you want to execute %s?", call.FunctionName)).
				// 	Affirmative("Yes").
				// 	Negative("No").
				// 	Value(&confirm).
				// 	WithTheme(huh.ThemeCatppuccin()).
				// 	Run(); err != nil {
				// 	color.Red("Error getting confirmation: %v", err)
				// 	continue
				// }

				// if !confirm {
				// 	color.Red("Tool call %s was cancelled by the user.", call.FunctionName)
				// 	a.AddMemoryEntry(memory.MemoryEntry{
				// 		Role:       "tool",
				// 		Message:    "Tool call cancelled by user",
				// 		ToolName:   call.FunctionName,
				// 		ToolCallID: call.ID,
				// 	})
				// 	continue
				// }

				output, _ := a.HandleToolCall(ctx, call)
				results = append(results, memory.ObservationResult{
					SourceCallID: call.ID,
					Content:      output,
				})
			}
			entry.Observation = memory.Observation{Results: results}
		}

		a.AddMemoryEntry(entry)

		if len(result.ToolCalls) == 0 {
			break
		}
	}

	if iterationCount >= a.maxIterations {
		color.Yellow("\nWarning: Maximum iterations (%d) reached. The agent loop was terminated.\n", a.maxIterations)
	}

	return nil
}

func (a *Agent) nextStepID() int {
	return len(a.memory) + 1
}

func mapToolCalls(calls []tools.ToolCall) []memory.ToolCall {
	if len(calls) == 0 {
		return nil
	}
	toolCalls := make([]memory.ToolCall, 0, len(calls))
	for _, call := range calls {
		toolCalls = append(toolCalls, memory.ToolCall{
			ToolCallID:   call.ID,
			FunctionName: call.FunctionName,
			Arguments:    call.Arguments,
		})
	}
	return toolCalls
}

package main

import (
	"fmt"
	"strings"

	"github.com/charmbracelet/lipgloss"
	"github.com/mightymoud/arlocode/internal/tui/layers"
)

func layersDemo() {
	fmt.Println("=== Layer Rendering Examples ===")

	// Example 1: Basic Overlay
	example1BasicOverlay()

	// Example 2: Z-Order Priority
	example2ZOrderPriority()

	// Example 3: Positioned Layers
	example3PositionedLayers()

	// Example 4: Modal Dialog Over Content
	example4ModalDialog()

	// Example 5: Using Compose API
	example5ComposeAPI()

	// Example 6: Transparency vs Opaque
	example6TransparencyVsOpaque()
}

// Example 1: Basic overlay of foreground on background
func example1BasicOverlay() {
	fmt.Println("--- Example 1: Basic Overlay ---")

	width, height := 20, 5

	// Background: filled with dots
	background := strings.Repeat(strings.Repeat(".", width)+"\n", height-1) +
		strings.Repeat(".", width)

	// Foreground: A simple box
	foreground := "┌────────┐\n│ HELLO! │\n└────────┘"

	result := layers.OverlaySimple(background, foreground, width, height)
	fmt.Println(result)
	fmt.Println()
}

// Example 2: Demonstrating Z-order priority
func example2ZOrderPriority() {
	fmt.Println("--- Example 2: Z-Order Priority ---")
	fmt.Println("Three layers at same position with Z=0, Z=1, Z=2")
	fmt.Println("Highest Z wins:")

	canvas := layers.NewCanvas(15, 3)

	// Layer at Z=0
	canvas.AddLayer(layers.NewLayer("AAAAAAAAAA", 0))

	// Layer at Z=1 (partially overlaps)
	canvas.AddLayer(layers.NewLayer("  BBBBBB", 1))

	// Layer at Z=2 (overlaps B)
	canvas.AddLayer(layers.NewLayer("    CCCC", 2))

	fmt.Println(canvas.Render())
	fmt.Println("Result: A shows where nothing covers it, B shows where C doesn't cover, C on top")
	fmt.Println()
}

// Example 3: Layers at different positions
func example3PositionedLayers() {
	fmt.Println("--- Example 3: Positioned Layers ---")

	canvas := layers.NewCanvas(30, 10)

	// Fill background
	bg := ""
	for i := 0; i < 10; i++ {
		bg += strings.Repeat("░", 30)
		if i < 9 {
			bg += "\n"
		}
	}
	canvas.AddLayer(layers.NewLayer(bg, 0))

	// Top-left box at Z=1
	box1 := "┌───┐\n│ 1 │\n└───┘"
	canvas.AddLayer(layers.NewLayer(box1, 1).WithOffset(2, 1))

	// Overlapping box at Z=2
	box2 := "┌───┐\n│ 2 │\n└───┘"
	canvas.AddLayer(layers.NewLayer(box2, 2).WithOffset(4, 2))

	// Bottom-right box at Z=1
	box3 := "┌───┐\n│ 3 │\n└───┘"
	canvas.AddLayer(layers.NewLayer(box3, 1).WithOffset(22, 6))

	fmt.Println(canvas.Render())
	fmt.Println()
}

// Example 4: Modal dialog overlaying content
func example4ModalDialog() {
	fmt.Println("--- Example 4: Modal Dialog Over Content ---")

	width, height := 40, 12

	canvas := layers.NewCanvas(width, height)

	// Main content (Z=0)
	contentStyle := lipgloss.NewStyle().
		Width(width - 4).
		Border(lipgloss.RoundedBorder())

	mainContent := contentStyle.Render(
		"This is the main application content.\n" +
			"It contains important information.\n" +
			"A modal will appear on top of this.")

	canvas.AddLayer(layers.NewLayer(mainContent, 0).WithOffset(2, 1))

	// Modal dialog (Z=1)
	modalStyle := lipgloss.NewStyle().
		Width(24).
		Border(lipgloss.DoubleBorder()).
		BorderForeground(lipgloss.Color("9")).
		Padding(0, 1)

	modal := modalStyle.Render(
		"⚠ Confirm Action?\n" +
			"[Yes]  [No]")

	// Center the modal
	modalLayer := layers.CenterLayer(modal, 1, width, height)
	canvas.AddLayer(modalLayer)

	fmt.Println(canvas.Render())
	fmt.Println()
}

// Example 5: Using the Compose API for fluent layer building
func example5ComposeAPI() {
	fmt.Println("--- Example 5: Using Compose API ---")

	result := layers.NewCompose(25, 7).
		Layer(strings.Repeat(strings.Repeat("▒", 25)+"\n", 6)+strings.Repeat("▒", 25), 0, 0, 0).
		CenteredLayer("═══════════\n  CENTER  \n═══════════", 1).
		Render()

	fmt.Println(result)
	fmt.Println()
}

// Example 6: Difference between Render (transparent) and RenderOpaque
func example6TransparencyVsOpaque() {
	fmt.Println("--- Example 6: Transparency vs Opaque ---")

	width, height := 20, 5

	// Background
	bg := ""
	for i := 0; i < height; i++ {
		bg += strings.Repeat("X", width)
		if i < height-1 {
			bg += "\n"
		}
	}

	// Foreground with spaces (which act as transparent or opaque)
	fg := "  HELLO  "

	// Transparent render - spaces show background through
	canvas1 := layers.NewCanvas(width, height)
	canvas1.AddLayer(layers.NewLayer(bg, 0))
	canvas1.AddLayer(layers.NewLayer(fg, 1).WithOffset(5, 2))

	fmt.Println("Transparent render (spaces show background):")
	fmt.Println(canvas1.Render())

	// Opaque render - spaces overwrite background
	canvas2 := layers.NewCanvas(width, height)
	canvas2.AddLayer(layers.NewLayer(bg, 0))
	canvas2.AddLayer(layers.NewLayer(fg, 1).WithOffset(5, 2))

	fmt.Println("\nOpaque render (spaces cover background):")
	fmt.Println()
}

package main

import (
	"fmt"
	"os"
	"time"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
	"github.com/mightymoud/arlocode/internal/tui/layers"
	"github.com/mightymoud/arlocode/internal/tui/notifications"
)

// tickMsg is sent on each animation frame
type tickMsg time.Time

// Model holds the application state
type model struct {
	width         int
	height        int
	notifications *notifications.NotificationManager
	canvas        *layers.Canvas
}

func initialModel() model {
	return model{
		width:         80,
		height:        24,
		notifications: notifications.NewNotificationManager(80, 24),
	}
}

func (m model) Init() tea.Cmd {
	// Start with a welcome notification
	m.notifications.PushInfo("Welcome!", "Press keys to trigger different notifications")
	return tick()
}

// tick returns a command that sends a tickMsg after a short delay
func tick() tea.Cmd {
	return tea.Tick(time.Second/60, func(t time.Time) tea.Msg {
		return tickMsg(t)
	})
}

func (m model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.KeyMsg:
		switch msg.String() {
		case "q", "ctrl+c", "esc":
			return m, tea.Quit

		case "i":
			m.notifications.PushInfo("Info", "This is an informational message")
			return m, nil

		case "s":
			m.notifications.PushSuccess("Success!", "The operation completed successfully")
			return m, nil

		case "w":
			m.notifications.PushWarning("Warning", "Something might need your attention")
			return m, nil

		case "e":
			m.notifications.PushError("Error", "Something went wrong! Please check the logs.")
			return m, nil

		case "d":
			m.notifications.DismissAll()
			return m, nil

		case "m":
			// Push multiple notifications rapidly
			m.notifications.PushInfo("First", "This is the first notification")
			m.notifications.PushSuccess("Second", "This is the second one")
			m.notifications.PushWarning("Third", "And here's a third!")
			return m, nil
		}

	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.notifications.UpdateScreenSize(msg.Width, msg.Height)
		return m, nil

	case tickMsg:
		// Update notification animations
		m.notifications.Update()
		// Continue ticking if there are active notifications
		if m.notifications.HasActiveNotifications() {
			return m, tick()
		}
		// Even with no notifications, keep ticking to catch new ones
		return m, tick()
	}

	return m, nil
}

func (m model) View() string {
	// Create the main content (background)
	mainContent := m.renderMainContent()

	// Create canvas for layering
	canvas := layers.NewCanvas(m.width, m.height)

	// Add main content as base layer
	canvas.AddLayer(layers.NewLayer(mainContent, 0))

	// Add notifications as overlay layer
	notifContent, x, y := m.notifications.RenderWithPosition()
	if notifContent != "" {
		canvas.AddLayer(layers.NewLayer(notifContent, 100).WithOffset(x, y))
	}

	return canvas.Render()
}

func (m model) renderMainContent() string {
	titleStyle := lipgloss.NewStyle().
		Bold(true).
		Foreground(lipgloss.Color("205")).
		MarginBottom(1)

	helpStyle := lipgloss.NewStyle().
		Foreground(lipgloss.Color("241"))

	keyStyle := lipgloss.NewStyle().
		Foreground(lipgloss.Color("39")).
		Bold(true)

	title := titleStyle.Render("🔔 Notification System Demo")

	help := lipgloss.JoinVertical(lipgloss.Left,
		"",
		helpStyle.Render("Press keys to trigger notifications:"),
		"",
		fmt.Sprintf("  %s  Info notification", keyStyle.Render("i")),
		fmt.Sprintf("  %s  Success notification", keyStyle.Render("s")),
		fmt.Sprintf("  %s  Warning notification", keyStyle.Render("w")),
		fmt.Sprintf("  %s  Error notification", keyStyle.Render("e")),
		fmt.Sprintf("  %s  Multiple notifications", keyStyle.Render("m")),
		fmt.Sprintf("  %s  Dismiss all", keyStyle.Render("d")),
		"",
		fmt.Sprintf("  %s  Quit", keyStyle.Render("q")),
		"",
		helpStyle.Render(fmt.Sprintf("Active notifications: %d", m.notifications.Count())),
	)

	content := lipgloss.JoinVertical(lipgloss.Left, title, help)

	// Center the content
	return lipgloss.Place(m.width, m.height, lipgloss.Center, lipgloss.Center, content)
}

func main() {
	p := tea.NewProgram(initialModel(), tea.WithAltScreen())
	if _, err := p.Run(); err != nil {
		fmt.Printf("Error running program: %v\n", err)
		os.Exit(1)
	}
}

package main

import (
	"fmt"
	"os"
	"time"

	"github.com/charmbracelet/bubbles/textinput"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
	"github.com/kjk/flex"

	"github.com/mightymoud/arlocode/internal/tui/layers"
	"github.com/mightymoud/arlocode/internal/tui/notifications"
)

type model struct {
	width         int
	height        int
	showModal     bool
	activeLayer   int // 0 = background focused, 1 = modal focused
	notifications *notifications.NotificationManager
	modalInput    textinput.Model
}

// tickMsg is sent on each animation frame for notifications
type tickMsg time.Time

func (m model) Init() tea.Cmd {
	return tea.Batch(tea.EnterAltScreen, tick())
}

// tick returns a command that sends a tickMsg after a short delay
func tick() tea.Cmd {
	return tea.Tick(time.Second/60, func(t time.Time) tea.Msg {
		return tickMsg(t)
	})
}

func (m model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	var cmd tea.Cmd
	var cmds []tea.Cmd

	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		if m.notifications != nil {
			m.notifications.UpdateScreenSize(msg.Width, msg.Height)
		}
	case tickMsg:
		// Update notification animations
		if m.notifications != nil {
			m.notifications.Update()
		}
		return m, tick()
	case tea.KeyMsg:
		// If modal is open, handle modal-specific keys first
		if m.showModal {
			switch msg.String() {
			case "esc":
				// Close modal and blur input
				m.showModal = false
				m.modalInput.Blur()
				return m, nil
			case "enter":
				// Submit the input value (you can do something with it here)
				if m.notifications != nil && m.modalInput.Value() != "" {
					m.notifications.PushSuccess("Submitted!", m.modalInput.Value())
					m.modalInput.SetValue("")
				}
				m.showModal = false
				m.modalInput.Blur()
				return m, nil
			default:
				// Route all other keys to the textinput
				m.modalInput, cmd = m.modalInput.Update(msg)
				cmds = append(cmds, cmd)
				return m, tea.Batch(cmds...)
			}
		}

		// Handle keys when modal is NOT open
		switch msg.String() {
		case " ":
			m.showModal = !m.showModal
			if m.showModal {
				// Focus the input when modal opens
				m.modalInput.Focus()
				cmds = append(cmds, textinput.Blink)
			} else {
				m.modalInput.Blur()
			}
		case "tab":
			m.activeLayer = (m.activeLayer + 1) % 2
		case "i":
			if m.notifications != nil {
				m.notifications.PushInfo("Info", "This is an informational message")
			}
		case "s":
			if m.notifications != nil {
				m.notifications.PushSuccess("Success!", "The operation completed successfully")
			}
		case "w":
			if m.notifications != nil {
				m.notifications.PushWarning("Warning", "Something might need your attention")
			}
		case "e":
			if m.notifications != nil {
				m.notifications.PushError("Error", "Something went wrong!")
			}
		case "d":
			if m.notifications != nil {
				m.notifications.DismissAll()
			}
		case "q", "ctrl+c":
			return m, tea.Quit
		}
	}
	return m, tea.Batch(cmds...)
}

func (m model) View() string {
	if m.width == 0 || m.height == 0 {
		return "Loading..."
	}

	// =========================================================================
	// FLEXBOX LAYOUT SETUP
	// =========================================================================

	// 1. Create the Root Node
	root := flex.NewNode()
	root.StyleSetWidth(float32(m.width))
	root.StyleSetHeight(float32(m.height))
	root.StyleSetFlexDirection(flex.FlexDirectionColumn)

	// 2. Define Children Nodes
	header := flex.NewNode()
	header.StyleSetHeight(3) // 3 rows high for header
	header.StyleSetFlexShrink(0)

	mainContent := flex.NewNode()
	mainContent.StyleSetFlexGrow(1) // Fills remaining space

	footer := flex.NewNode()
	footer.StyleSetHeight(1) // 1 row for footer/status bar
	footer.StyleSetFlexShrink(0)

	// Insert children into root
	root.InsertChild(header, 0)
	root.InsertChild(mainContent, 1)
	root.InsertChild(footer, 2)

	// 3. Calculate Layout
	flex.CalculateLayout(root, float32(m.width), float32(m.height), flex.DirectionLTR)

	// =========================================================================
	// RENDER EACH PANEL USING CALCULATED FLEX DIMENSIONS
	// =========================================================================

	// Create a canvas for layer composition
	canvas := layers.NewCanvas(m.width, m.height)

	// --- HEADER PANEL ---
	headerWidth := int(header.LayoutGetWidth())
	headerHeight := int(header.LayoutGetHeight())
	headerY := int(header.LayoutGetTop())

	headerStyle := lipgloss.NewStyle().
		Width(headerWidth).
		Height(headerHeight).
		Background(lipgloss.Color("#0f3460")).
		Foreground(lipgloss.Color("#e0e0e0")).
		Padding(0, 2).
		Align(lipgloss.Left, lipgloss.Center)

	headerContent := headerStyle.Render(
		lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("#e94560")).Render("⚡ ArloCode") +
			"  │  Flexbox Layout Demo  │  SPACE toggle modal, i/s/w/e notifications, Q quit",
	)
	canvas.AddLayer(layers.NewLayer(headerContent, 0).WithOffset(0, headerY))

	// --- MAIN CONTENT PANEL ---
	mainWidth := int(mainContent.LayoutGetWidth())
	mainHeight := int(mainContent.LayoutGetHeight())
	mainY := int(mainContent.LayoutGetTop())

	// Background pattern for main area
	bgStyle := lipgloss.NewStyle().
		Width(mainWidth).
		Height(mainHeight).
		Background(lipgloss.Color("#1a1a2e")).
		Foreground(lipgloss.Color("#4a4a6a"))

	pattern := ""
	for y := 0; y < mainHeight; y++ {
		row := ""
		for x := 0; x < mainWidth; x++ {
			if (x+y)%4 == 0 {
				row += "·"
			} else {
				row += " "
			}
		}
		pattern += row
		if y < mainHeight-1 {
			pattern += "\n"
		}
	}
	backgroundContent := bgStyle.Render(pattern)
	canvas.AddLayer(layers.NewLayer(backgroundContent, 1).WithOffset(0, mainY))

	// --- CENTERED CONTENT PANEL (inside main) ---
	contentPanelWidth := min(60, mainWidth-10)
	contentPanelHeight := min(15, mainHeight-4)

	contentPanelStyle := lipgloss.NewStyle().
		Width(contentPanelWidth).
		Height(contentPanelHeight).
		Background(lipgloss.Color("#16213e")).
		Foreground(lipgloss.Color("#e0e0e0")).
		Border(lipgloss.RoundedBorder()).
		BorderForeground(lipgloss.Color("#0f3460")).
		Padding(1, 2).
		Align(lipgloss.Center, lipgloss.Center)

	contentPanel := contentPanelStyle.Render(
		lipgloss.JoinVertical(lipgloss.Center,
			lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("#e94560")).Render("[Flexbox Layout Demo]"),
			"",
			"This panel uses github.com/kjk/flex",
			"for flexbox-based terminal layout!",
			"",
			fmt.Sprintf("Header: %dw × %dh", headerWidth, headerHeight),
			fmt.Sprintf("Main:   %dw × %dh", mainWidth, mainHeight),
			fmt.Sprintf("Footer: %dw × %dh", int(footer.LayoutGetWidth()), int(footer.LayoutGetHeight())),
			"",
			lipgloss.NewStyle().Faint(true).Render("Press SPACE to toggle modal"),
		),
	)

	// Center the content panel within main area
	contentPanelX := (mainWidth - lipgloss.Width(contentPanel)) / 2
	contentPanelY := mainY + (mainHeight-lipgloss.Height(contentPanel))/2
	canvas.AddLayer(layers.NewLayer(contentPanel, 2).WithOffset(contentPanelX, contentPanelY))

	// --- MODAL OVERLAY (conditionally shown) ---
	if m.showModal {
		modalWidth := 50
		// modalHeight := 12

		modalStyle := lipgloss.NewStyle().
			Width(modalWidth).
			Background(lipgloss.Color("#2d132c")).
			Foreground(lipgloss.Color("#ffffff")).
			Border(lipgloss.RoundedBorder()).
			BorderForeground(lipgloss.Color("#ee4540")).
			Padding(1, 2)

		// Style for the input label
		labelStyle := lipgloss.NewStyle().
			Foreground(lipgloss.Color("#aaaaaa"))

		modalContent := modalStyle.Render(
			lipgloss.JoinVertical(lipgloss.Left,
				lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("#ffd460")).Render("Modal with Input"),
				"",
				labelStyle.Render("Enter something:"),
				m.modalInput.View(),
				"",
				lipgloss.NewStyle().Faint(true).Render("Enter to submit • Esc to close"),
			),
		)

		// Center the modal on screen
		modalX := (m.width - lipgloss.Width(modalContent)) / 2
		modalY := (m.height - lipgloss.Height(modalContent)) / 2
		canvas.AddLayer(layers.NewLayer(modalContent, 5).WithOffset(modalX, modalY))
	}

	// --- FOOTER/STATUS BAR ---
	footerWidth := int(footer.LayoutGetWidth())
	footerHeight := int(footer.LayoutGetHeight())
	footerY := int(footer.LayoutGetTop())

	footerStyle := lipgloss.NewStyle().
		Width(footerWidth).
		Height(footerHeight).
		Background(lipgloss.Color("#0f3460")).
		Foreground(lipgloss.Color("#e0e0e0")).
		Padding(0, 1)

	modalStatus := "Modal: OFF"
	if m.showModal {
		modalStatus = lipgloss.NewStyle().Foreground(lipgloss.Color("#00ff00")).Render("Modal: ON")
	}

	footerContent := footerStyle.Render(
		fmt.Sprintf("Size: %dx%d │ %s │ Flexbox: Header→Main→Footer",
			m.width, m.height, modalStatus),
	)
	canvas.AddLayer(layers.NewLayer(footerContent, 10).WithOffset(0, footerY))

	// --- NOTIFICATION OVERLAY ---
	if m.notifications != nil {
		notifContent, notifX, notifY := m.notifications.RenderWithPosition()
		if notifContent != "" {
			canvas.AddLayer(layers.NewLayer(notifContent, 100).WithOffset(notifX, notifY))
		}
	}

	return canvas.RenderWithLipgloss()
}

func main() {
	// Create and configure the text input for the modal
	ti := textinput.New()
	ti.Placeholder = "Type here..."
	ti.Width = 40
	ti.CharLimit = 100

	// Style the text input
	ti.PromptStyle = lipgloss.NewStyle().Foreground(lipgloss.Color("#ee4540"))
	ti.TextStyle = lipgloss.NewStyle().Foreground(lipgloss.Color("#ffffff"))
	ti.PlaceholderStyle = lipgloss.NewStyle().Foreground(lipgloss.Color("#666666"))
	ti.Cursor.Style = lipgloss.NewStyle().Foreground(lipgloss.Color("#ffd460"))

	// Initialize the model with notification manager and text input
	m := model{
		notifications: notifications.NewNotificationManager(80, 24),
		modalInput:    ti,
	}

	p := tea.NewProgram(m)
	if _, err := p.Run(); err != nil {
		fmt.Printf("Alas, there's been an error: %v", err)
		os.Exit(1)
	}

}
